class SubscriptionPlanUpdateSerializer(serializers.ModelSerializer):
    payment_profile = PaymentProfileSerializer()

    class Meta:
        model = Subscription
        fields = ['plan_name', 'tier', 'payment_profile']

    def update(self, instance, validated_data):
        profile_data = validated_data.pop('payment_profile')
        if instance.payment_profile_id != profile_data.get('id'):
            raise serializers.ValidationError("Invalid payment profile specified for this subscription.")
        PaymentProfile.objects.filter(id=instance.payment_profile_id, user=instance.user).update(**profile_data)
        return super().update(instance, validated_data)
